/**
 * GSAP 3 ScrambleTextPlugin
 */
(function () {
  var gsap;
  var ScrambleTextPlugin = {
    name: "scrambleText",
    version: "3.12.2",
    register: function (core) {
      gsap = core;
    },
    init: function (target, val) {
      this._target = target;
      var text = (typeof val === "string" ? val : (val && val.text !== undefined ? val.text : target.textContent || "")).trim();
      var chars = (val && val.chars && val.chars !== "upperAndLowerCase") ? val.chars : "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz!@#$%^&*";
      this._text = text;
      this._chars = chars;
      this._len = text.length;
      this._props.push("scrambleText");
    },
    render: function (ratio, data) {
      var target = data._target;
      if (!target) return;
      if (ratio >= 1) {
        target.textContent = data._text;
        return;
      }
      var solved = Math.floor(ratio * data._len);
      var result = data._text.substring(0, solved);
      for (var i = solved; i < data._len; i++) {
        var char = data._text[i];
        if (char === " " || char === "\n" || char === "\t") {
          result += char;
        } else {
          result += data._chars[Math.floor(Math.random() * data._chars.length)];
        }
      }
      target.textContent = result;
    }
  };

  if (typeof window !== "undefined") {
    window.ScrambleTextPlugin = ScrambleTextPlugin;
    if (window.gsap && typeof window.gsap.registerPlugin === "function") {
      window.gsap.registerPlugin(ScrambleTextPlugin);
    }
  }
  if (typeof module !== "undefined" && module.exports) {
    module.exports = ScrambleTextPlugin;
  }
})();
